-- Slovakia deep-dive page translations: page fields, stats, cards,
-- penalty rows, steps, portal.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'es', 'Peppol de 5 esquinas ("Digital Postman")', 'Esta página de análisis refleja la orientación técnica disponible públicamente a julio de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. El CIUS nacional de Eslovaquia, las especificaciones de API y la normativa del Ministerio de Finanzas aún se están finalizando — confirme los requisitos actuales directamente con la Dirección Financiera antes de construir una integración.', 'Eslovaquia ya ha pasado por esto antes — se planificó un marco B2B voluntario para 2022 que se archivó discretamente. Esta vez el mandato está legislado con una fecha firme.', 'Eslovaquia no ha publicado un CIUS nacional — se apoya en el estándar base EN 16931 en lugar de añadir una capa claramente eslovaca.', 'La etiqueta de "5 esquinas" importa aquí: los Digital Postmen no solo mueven facturas entre socios comerciales, también reportan los datos a la autoridad fiscal en el mismo paso.', 'La fase voluntaria de 2026 existe precisamente para que las empresas puedan resolver los problemas de integración antes de que el mandato tenga consecuencias reales.', 'Eslovaquia está adoptando explícitamente un enfoque educativo durante la primera mitad de 2027 — pero las multas detrás de ese período de gracia son reales.' FROM countries WHERE name_en = 'Slovakia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'de', 'Peppol 5-Ecken-Modell ("Digital Postman")', 'Diese Länderanalyse spiegelt öffentlich verfügbare technische Hinweise mit Stand Juli 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Die slowakische nationale CIUS, die API-Spezifikationen und die Vorschriften des Finanzministeriums werden noch finalisiert — bestätigen Sie aktuelle Anforderungen direkt bei der Finanzdirektion, bevor Sie eine Integration aufbauen.', 'Die Slowakei kennt das bereits — ein freiwilliger B2B-Rahmen war für 2022 geplant und wurde still zurückgestellt. Diesmal ist die Pflicht mit einem festen Termin gesetzlich verankert.', 'Die Slowakei hat keine nationale CIUS veröffentlicht — sie stützt sich auf den europäischen Basisstandard EN 16931, statt eine eigene slowakische Ebene hinzuzufügen.', 'Die Bezeichnung "5-Ecken" ist hier entscheidend: Digital Postmen bewegen Rechnungen nicht nur zwischen Handelspartnern, sie melden die Daten im selben Schritt an die Finanzverwaltung.', 'Die freiwillige Phase 2026 existiert genau deshalb, damit Unternehmen Integrationsprobleme lösen können, bevor die Pflicht Konsequenzen hat.', 'Die Slowakei verfolgt in der ersten Hälfte von 2027 ausdrücklich einen pädagogischen Ansatz — aber die Bußgelder hinter dieser Übergangsfrist sind real.' FROM countries WHERE name_en = 'Slovakia';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'fr', 'Peppol à 5 coins (« Digital Postman »)', 'Cette analyse par pays reflète les directives techniques publiquement disponibles à juillet 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. La CIUS nationale de la Slovaquie, les spécifications API et la réglementation du ministère des Finances sont encore en cours de finalisation — confirmez les exigences actuelles directement auprès de la Direction financière avant de construire une intégration.', 'La Slovaquie est déjà passée par là — un cadre B2B volontaire était prévu pour 2022 et a été discrètement mis de côté. Cette fois, l''obligation est inscrite dans la loi avec une date ferme.', 'La Slovaquie n''a pas publié de CIUS nationale — elle s''appuie sur la norme européenne de base EN 16931 plutôt que d''y ajouter une couche nettement slovaque.', 'L''étiquette « à 5 coins » compte ici : les Digital Postmen ne se contentent pas de faire circuler les factures entre partenaires commerciaux, ils déclarent aussi les données à l''administration fiscale dans la même étape.', 'La phase volontaire de 2026 existe précisément pour permettre aux entreprises de résoudre les problèmes d''intégration avant que l''obligation n''ait de réelles conséquences.', 'La Slovaquie adopte explicitement une approche pédagogique jusqu''à la mi-2027 — mais les amendes derrière cette période de grâce sont bien réelles.' FROM countries WHERE name_en = 'Slovakia';

