INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Sintaxis y estándar', '[["Estándar", "EN 16931"], ["Sintaxis aceptadas", "UBL 2.1 o UN/CEFACT CII"], ["CIUS nacional", "Aún no implementado — en evaluación"]]', 'A diferencia del RO_CIUS de Rumanía o el HR-FISK de Croacia, Eslovaquia está construyendo actualmente sobre el estándar base europeo simple — esté atento a la definición de un CIUS nacional a medida que avance el despliegue.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Syntax & Standard', '[["Standard", "EN 16931"], ["Akzeptierte Syntaxen", "UBL 2.1 oder UN/CEFACT CII"], ["Nationale CIUS", "Noch nicht umgesetzt — wird geprüft"]]', 'Anders als Rumäniens RO_CIUS oder Kroatiens HR-FISK baut die Slowakei derzeit auf dem einfachen europäischen Basisstandard auf — achten Sie darauf, ob im Zuge des Rollouts eine nationale CIUS definiert wird.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Syntaxe et norme', '[["Norme", "EN 16931"], ["Syntaxes acceptées", "UBL 2.1 ou UN/CEFACT CII"], ["CIUS nationale", "Pas encore mise en œuvre — en cours d''évaluation"]]', 'Contrairement au RO_CIUS de la Roumanie ou au HR-FISK de la Croatie, la Slovaquie s''appuie actuellement sur la norme européenne de base simple — surveillez la définition d''une CIUS nationale à mesure que le déploiement mûrit.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Identificadores', '[["Esquema Peppol", "0245 — SG:DIC"], ["Identificador", "NIF eslovaco de 10 dígitos (DIČ)"], ["Emitido por", "Administración Financiera de la República Eslovaca"]]', 'Utilice el esquema 0245 al registrar usuarios finales eslovacos en la red Peppol — este es el identificador que se resuelve al DIČ concreto del destinatario a efectos de enrutamiento.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Kennungen', '[["Peppol-Schema", "0245 — SG:DIC"], ["Kennung", "10-stellige slowakische Steuernummer (DIČ)"], ["Ausgestellt von", "Finanzverwaltung der Slowakischen Republik"]]', 'Verwenden Sie das Schema 0245 bei der Registrierung slowakischer Endnutzer im Peppol-Netzwerk — dies ist die Kennung, die für Routingzwecke auf die DIČ eines bestimmten Empfängers verweist.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Identifiants', '[["Schéma Peppol", "0245 — SG:DIC"], ["Identifiant", "Numéro fiscal slovaque à 10 chiffres (DIČ)"], ["Délivré par", "Administration financière de la République slovaque"]]', 'Utilisez le schéma 0245 lors de l''enregistrement des utilisateurs finaux slovaques sur le réseau Peppol — c''est l''identifiant qui se résout au DIČ d''un destinataire donné à des fins de routage.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Lo que queda expresamente excluido', '[["PDF / imágenes escaneadas", "No se consideran facturas electrónicas"], ["Transacciones B2C", "Fuera de alcance"], ["Otras exenciones", "Información clasificada; ciertos organismos públicos"]]', 'El documento de preguntas frecuentes (9/DPH/2025) es explícito: una factura electrónica se define como un archivo XML estructurado legible por máquina, sin más — nada que simplemente parezca una factura cualifica.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Was ausdrücklich ausgeschlossen ist', '[["PDFs / gescannte Bilder", "Gelten nicht als E-Rechnungen"], ["B2C-Transaktionen", "Nicht im Anwendungsbereich"], ["Weitere Ausnahmen", "Verschlusssachen; bestimmte Behörden"]]', 'Das FAQ-Dokument (9/DPH/2025) ist eindeutig: Eine E-Rechnung ist als maschinenlesbare strukturierte XML-Datei definiert, Punkt — alles, was nur wie eine Rechnung aussieht, zählt nicht.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Ce qui est explicitement exclu', '[["PDF / images scannées", "Ne sont pas considérées comme des factures électroniques"], ["Transactions B2C", "Hors champ"], ["Autres exemptions", "Informations classifiées ; certains organismes publics"]]', 'Le document FAQ (9/DPH/2025) est explicite : une facture électronique est définie comme un fichier XML structuré lisible par machine, un point c''est tout — tout ce qui ressemble simplement à une facture ne suffit pas.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Archivo y plazos', '[["Conservación", "10 años, en formato XML original"], ["Plazo de emisión (hasta 2030)", "15 días desde el devengo"], ["Plazo de emisión (desde 2030)", "Se reduce a 10 días"]]', 'Enviar la factura a través de un Digital Postman dentro del plazo es lo que cumple la obligación de emisión — el plazo se cuenta desde la transmisión, no solo desde la generación.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Archivierung und Fristen', '[["Aufbewahrung", "10 Jahre, im ursprünglichen XML-Format"], ["Ausstellungsfrist (bis 2030)", "15 Tage ab dem Steuertatbestand"], ["Ausstellungsfrist (ab 2030)", "Verkürzt sich auf 10 Tage"]]', 'Der Versand der Rechnung über einen Digital Postman innerhalb der Frist erfüllt die Ausstellungspflicht — die Frist läuft ab der Übermittlung, nicht nur ab der Erstellung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Archivage et délais', '[["Conservation", "10 ans, au format XML d''origine"], ["Délai d''émission (jusqu''en 2030)", "15 jours à compter du fait générateur"], ["Délai d''émission (à partir de 2030)", "Réduit à 10 jours"]]', 'L''envoi de la facture via un Digital Postman dans le délai imparti est ce qui satisfait l''obligation d''émission — le délai court à partir de la transmission, pas seulement de la génération.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'El modelo de 5 esquinas', '[["Esquinas 1–4", "Intercambio Peppol estándar (proveedor → PA → PA → comprador)"], ["Esquina 5", "Reporte en tiempo real a la Administración Financiera"], ["Término del proveedor de servicios", "\"Digitálni poštári\" (Carteros Digitales)"]]', 'Este es un avance arquitectónico genuino más allá de los modelos simples de 4 esquinas de Bélgica o el Reino Unido — el tramo de reporte está integrado en la misma transmisión, no es una presentación separada.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Das 5-Ecken-Modell', '[["Ecken 1–4", "Standard-Peppol-Austausch (Lieferant → AP → AP → Käufer)"], ["Ecke 5", "Echtzeitmeldung an die Finanzverwaltung"], ["Begriff für den Dienstanbieter", "\"Digitálni poštári\" (Digitale Postboten)"]]', 'Dies ist ein echter architektonischer Schritt über die einfachen 4-Ecken-Modelle Belgiens oder des Vereinigten Königreichs hinaus — der Meldeschritt ist in dieselbe Übermittlung integriert, keine separate Einreichung.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Le modèle à 5 coins', '[["Coins 1 à 4", "Échange Peppol standard (fournisseur → AP → AP → acheteur)"], ["Coin 5", "Déclaration en temps réel à l''Administration financière"], ["Terme pour le prestataire de service", "« Digitálni poštári » (Facteurs numériques)"]]', 'C''est une véritable avancée architecturale au-delà des simples modèles à 4 coins de la Belgique ou du Royaume-Uni — le volet déclaratif est intégré à la même transmission, pas une déclaration séparée.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'IS EFA frente a la red B2B', '[["IS EFA", "Plataforma central B2G/G2G, en funcionamiento desde 2023"], ["B2B", "Red de Digital Postman basada en Peppol, que extiende los mismos principios"]]', 'No confunda las dos — las facturas B2G a IS EFA usan UBL 2.1 o CII D16B directamente; las facturas B2B se mueven a través de Digital Postmen acreditados sobre Peppol, con IS eFaktúra recibiendo los datos reportados.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'IS EFA im Vergleich zum B2B-Netzwerk', '[["IS EFA", "Zentrale B2G-/G2G-Plattform, seit 2023 in Betrieb"], ["B2B", "Peppol-basiertes Digital-Postman-Netzwerk, das dieselben Prinzipien erweitert"]]', 'Verwechseln Sie die beiden nicht — B2G-Rechnungen an IS EFA verwenden direkt UBL 2.1 oder CII D16B; B2B-Rechnungen laufen über akkreditierte Digital Postmen über Peppol, wobei IS eFaktúra die gemeldeten Daten empfängt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'IS EFA face au réseau B2B', '[["IS EFA", "Plateforme centrale B2G/G2G, en service depuis 2023"], ["B2B", "Réseau Digital Postman basé sur Peppol, prolongeant les mêmes principes"]]', 'Ne confondez pas les deux — les factures B2G vers IS EFA utilisent directement UBL 2.1 ou CII D16B ; les factures B2B transitent via des Digital Postmen accrédités sur Peppol, IS eFaktúra recevant les données déclarées.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Validación y gestión de errores', '[["Validación previa al envío", "El Digital Postman señala errores de formato/datos antes de la transmisión"], ["Corrección posterior a la transmisión", "Nota de crédito formal + nueva factura corregida"], ["Modificación directa", "No es posible una vez transmitida"]]', 'El rechazo por parte del destinatario debe gestionarse bilateralmente entre proveedor y comprador — no existe una función de rechazo dentro de la propia red Peppol para este fin.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Validierung und Fehlerbehandlung', '[["Validierung vor dem Versand", "Digital Postman markiert Format-/Datenfehler vor der Übermittlung"], ["Korrektur nach der Übermittlung", "Formale Gutschrift + neue korrigierte Rechnung"], ["Direkte Änderung", "Nach der Übermittlung nicht möglich"]]', 'Eine Ablehnung durch den Empfänger muss bilateral zwischen Lieferant und Käufer geklärt werden — im Peppol-Netzwerk selbst gibt es dafür keine Ablehnungsfunktion.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Validation et gestion des erreurs', '[["Validation avant envoi", "Le Digital Postman signale les erreurs de format/données avant la transmission"], ["Correction après transmission", "Note de crédit formelle + nouvelle facture corrigée"], ["Modification directe", "Impossible une fois transmise"]]', 'Le rejet par le destinataire doit être géré bilatéralement entre le fournisseur et l''acheteur — il n''existe pas de fonction de rejet au sein du réseau Peppol lui-même à cette fin.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', 'Empresas extranjeras (contexto B2G)', '[["Canal", "Envío por correo electrónico"], ["Confirmación", "Confirmada o rechazada por correo electrónico por el gobierno"]]', 'Esta vía más ligera por correo electrónico se aplica específicamente a los escenarios B2G para entidades extranjeras — el B2B sigue requiriendo una relación con un Digital Postman una vez que se aplique el mandato de 2027.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', 'Ausländische Unternehmen (B2G-Kontext)', '[["Kanal", "E-Mail-basierte Einreichung"], ["Bestätigung", "Von der Behörde per E-Mail bestätigt oder abgelehnt"]]', 'Dieser leichtere E-Mail-Weg gilt speziell für B2G-Szenarien ausländischer Unternehmen — für B2B ist weiterhin eine Digital-Postman-Beziehung erforderlich, sobald die Pflicht ab 2027 gilt.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', 'Entreprises étrangères (contexte B2G)', '[["Canal", "Soumission par e-mail"], ["Confirmation", "Confirmée ou rejetée par e-mail par l''administration"]]', 'Cette voie allégée par e-mail s''applique spécifiquement aux scénarios B2G pour les entités étrangères — le B2B nécessite toujours une relation avec un Digital Postman une fois l''obligation de 2027 applicable.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'scope_transmission' AND dc.sort_order = 3;

