INSERT OR IGNORE INTO deep_dive_penalty_row_translations (row_id, lang, failure_description, fine_amount, annual_cap) SELECT dpr.id, 'fr', 'Infractions répétées', 'Jusqu''à 100 000 €', NULL FROM deep_dive_penalty_rows dpr JOIN countries c ON c.id = dpr.country_id WHERE c.name_en = 'Slovakia' AND dpr.sort_order = 1;

INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🎓 Enfoque educativo hasta mediados de 2027', NULL, NULL, '2026 y la primera mitad de 2027 sirven como períodos de gracia con énfasis en la educación en lugar del castigo — aunque las sanciones técnicamente aún pueden aplicarse tras la entrada en vigor en casos flagrantes.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🎓 Pädagogischer Ansatz bis Mitte 2027', NULL, NULL, '2026 und die erste Hälfte von 2027 dienen als Übergangsfristen mit Schwerpunkt auf Aufklärung statt Bestrafung — Bußgelder können jedoch technisch auch nach dem Start in besonders schweren Fällen verhängt werden.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🎓 Approche pédagogique jusqu''à mi-2027', NULL, NULL, '2026 et la première moitié de 2027 servent de périodes de grâce mettant l''accent sur la pédagogie plutôt que sur la sanction — bien que des amendes puissent techniquement encore s''appliquer après l''entrée en vigueur dans les cas les plus flagrants.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '📖 Dónde consultar la letra pequeña', NULL, NULL, 'Las preguntas frecuentes oficiales de la Dirección Financiera ("Najčastejšie otázky a odpovede k eFaktúre", documento 9/DPH/2025) y los estándares técnicos detallados (esquemas, listas de códigos, especificaciones de API Peppol) se están emitiendo mediante un reglamento de carácter general del Ministerio de Finanzas — consulte info-efaktura.sk y financnasprava.sk para actualizaciones.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '📖 Wo Sie das Kleingedruckte nachlesen können', NULL, NULL, 'Das offizielle FAQ der Finanzdirektion ("Najčastejšie otázky a odpovede k eFaktúre", Dokument 9/DPH/2025) sowie detaillierte technische Standards (Schemas, Codelisten, Peppol-API-Spezifikationen) werden über eine allgemein verbindliche Verordnung des Finanzministeriums veröffentlicht — prüfen Sie info-efaktura.sk und financnasprava.sk auf Updates.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '📖 Où consulter les détails', NULL, NULL, 'La FAQ officielle de la Direction financière (« Najčastejšie otázky a odpovede k eFaktúre », document 9/DPH/2025) ainsi que les normes techniques détaillées (schémas, listes de codes, spécifications API Peppol) sont publiées via un règlement d''application générale du ministère des Finances — consultez info-efaktura.sk et financnasprava.sk pour les mises à jour.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'es', '🔁 Un mandato que ya se ha retrasado antes', NULL, NULL, 'Dado que el anterior marco voluntario de 2022 se archivó, conviene tratar la fecha de 2027 con una confianza razonable, pero estando atento a posibles nuevos cambios de calendario a medida que se acerca el plazo.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'de', '🔁 Eine Pflicht, die schon einmal verschoben wurde', NULL, NULL, 'Da der frühere freiwillige Rahmen von 2022 zurückgestellt wurde, lohnt es sich, den Termin 2027 mit angemessenem Vertrauen zu behandeln, aber wachsam gegenüber weiteren Terminänderungen zu bleiben, je näher die Frist rückt.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'fr', '🔁 Une obligation déjà reportée par le passé', NULL, NULL, 'Étant donné que le précédent cadre volontaire de 2022 a été mis de côté, il convient de considérer la date de 2027 avec une confiance raisonnable, tout en restant attentif à d''éventuels nouveaux changements de calendrier à l''approche de l''échéance.', NULL, NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Slovakia' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Evalúe sus sistemas de facturación actuales', 'Compruebe la compatibilidad con la salida EN 16931 / UBL XML e identifique las actualizaciones necesarias antes de la entrada en vigor obligatoria.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bewerten Sie Ihre aktuellen Rechnungssysteme', 'Prüfen Sie die Kompatibilität mit der EN-16931-/UBL-XML-Ausgabe und identifizieren Sie notwendige Upgrades vor dem verpflichtenden Start.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Évaluez vos systèmes de facturation actuels', 'Vérifiez la compatibilité avec la sortie EN 16931 / UBL XML et identifiez les mises à niveau nécessaires avant l''entrée en vigueur obligatoire.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Seleccione y contrate un Digital Postman acreditado', 'Hágalo con suficiente antelación al 1 de enero de 2027 — y tenga en cuenta que a partir del 1 de julio de 2027 solo podrán usarse Digital Postmen certificados.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wählen und beauftragen Sie einen akkreditierten Digital Postman', 'Tun Sie dies rechtzeitig vor dem 1. Januar 2027 — und beachten Sie, dass ab dem 1. Juli 2027 ausschließlich zertifizierte Digital Postmen verwendet werden dürfen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Choisissez et contractez un Digital Postman accrédité', 'Faites-le bien avant le 1er janvier 2027 — et sachez qu''à partir du 1er juillet 2027, seuls des Digital Postmen certifiés pourront être utilisés.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Use la fase voluntaria de 2026 para probar de extremo a extremo', 'Regístrese voluntariamente para pilotar los flujos de envío, validación y corrección de facturas antes de que el mandato tenga consecuencias reales.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Nutzen Sie die freiwillige Phase 2026 für einen End-to-End-Test', 'Registrieren Sie sich freiwillig, um die Workflows für Rechnungsübermittlung, Validierung und Korrektur zu testen, bevor die Pflicht echte Konsequenzen hat.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Utilisez la phase volontaire de 2026 pour tester de bout en bout', 'Inscrivez-vous volontairement pour piloter les flux de soumission, de validation et de correction des factures avant que l''obligation n''ait de réelles conséquences.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Confirme que su ID de participante Peppol usa el esquema 0245', 'Asegúrese de que su DIČ de 10 dígitos está correctamente registrado bajo el esquema de identificador eslovaco — esto es lo que le hace enrutable en la red.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bestätigen Sie, dass Ihre Peppol-Teilnehmer-ID das Schema 0245 verwendet', 'Stellen Sie sicher, dass Ihre 10-stellige DIČ korrekt unter dem slowakischen Kennungsschema registriert ist — dies macht Sie im Netzwerk routbar.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Confirmez que votre identifiant participant Peppol utilise le schéma 0245', 'Assurez-vous que votre DIČ à 10 chiffres est correctement enregistré sous le schéma d''identifiant slovaque — c''est ce qui vous rend routable sur le réseau.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Forme a su personal en el flujo de corrección', 'Dado que la modificación directa de una factura transmitida no es posible, asegúrese de que su equipo entiende el proceso de nota de crédito más reemisión antes de necesitarlo bajo presión.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Schulen Sie Ihr Personal im Korrekturworkflow', 'Da eine direkte Änderung einer übermittelten Rechnung nicht möglich ist, stellen Sie sicher, dass Ihr Team den Prozess aus Gutschrift plus Neuausstellung versteht, bevor er unter Druck benötigt wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Formez votre personnel au processus de correction', 'La modification directe d''une facture transmise n''étant pas possible, assurez-vous que votre équipe comprend le processus de note de crédit suivie d''une réémission avant d''en avoir besoin sous pression.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Integre en su proceso el plazo de emisión de 15 días (pronto 10)', 'Automatice el envío cerca del devengo en lugar de agrupar por lotes — el plazo corre desde el hecho imponible, no desde el momento en que alguien se dispone a generar el archivo.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bauen Sie die 15-Tage- (bald 10-Tage-) Ausstellungsfrist in Ihren Prozess ein', 'Automatisieren Sie die Übermittlung nahe am Steuertatbestand, statt zu bündeln — die Frist läuft ab dem steuerauslösenden Ereignis, nicht erst ab dem Zeitpunkt, an dem jemand die Datei erzeugt.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Intégrez le délai d''émission de 15 jours (bientôt 10) à votre processus', 'Automatisez la soumission au plus près du fait générateur plutôt que par lots — le délai court à partir de l''événement imposable, pas à partir du moment où quelqu''un génère le fichier.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Slovakia' AND ds.sort_order = 5;

